IF SCHEMA_ID('stage') IS NULL
    EXEC('CREATE SCHEMA [stage]');
GO

CREATE OR ALTER VIEW [stage].[DimFacilitySource]
AS
select
    facility.Facility_BK,
    facility.FacilityName,
    facility.FacilityOtherNames,
    facility.SubSiteName,
    facility.SubSiteOtherNames,
    facility.FacilityType,
    facility.PrimaryCommodity,
    facility.CommoditiesProducts,
    facility.FacilityEquipment,
    facility.ActivityStatus,
    facility.Country,
    facility.GadmLevel0Code,
    facility.GadmLevel1Code,
    facility.GadmLevel2Code,
    facility.GadmLevel3Code,
    facility.GadmLevel4Code,
    facility.LocationGeometry,
    facility.Comment,
    facility.SurfaceAreaSquareKilometers,
    facility.ConcessionAreaSquareKilometers,
    facility.ProductionStartYear,
    facility.ProductionEndYear,
    facility.ActivityStatusYear
from [lh_silver].[dbo].[facility] as facility
GO
